export default class Queue<T> {
    public length: number;
    private _head?: Node<T>;
    private _tail?: Node<T>;

    constructor() {
        this.length = 0;
    }

    enqueue(item: T): void {
        const node: Node<T> = { value: item };
        this.length++;

        if (!this._tail) {
            this._head = node;
            this._tail = this._head;
            return;
        }

        this._tail.next = node;
        this._tail = node;
    }

    deque(): T | undefined {
        if (!this._head) {
            return undefined;
        }

        this.length–;

        const head = this._head;
        this._head = this._head.next;

        // free, for some other language we need to housekeeping as well
        head.next = undefined;

        return head.value;
    }

    peek(): T | undefined {
        return this._head?.value;
    }
}

