In C# Both the Interface version and the Abstract version works, which is better?

/*Abstract*/

abstract class BaseClass
{
    public abstract bool Validate();
}

class A : BaseClass
{
    public string? Email { get; set; }
    public string? Password { get; set; }

    public override bool Validate()
    {
        if (string.IsNullOrEmpty(Email)) return false;
        if (string.IsNullOrEmpty(Password)) return false;
        return true;
    }
}

class B : A
{
    public string? Phone { get; set; }

    public override bool Validate()
    {
        if (base.Validate()) return false;
        if (string.IsNullOrEmpty(Phone)) return false;
        return true;
    }
}
static class C
{
    public static bool ValidateAccount(BaseClass account)
    {
        return account.Validate();
    }
}

class Program
{
    static void Main(string[] args)
    {
        var instance = new B();
        Console.WriteLine(C.ValidateAccount(instance));
    }
}

/*Interface*/

interface I
{
    public bool Validate();
}

class A : I
{
    public string? Email { get; set; }
    public string? Password { get; set; }

    public virtual bool Validate()
    {
        if (string.IsNullOrEmpty(Email)) return false;
        if (string.IsNullOrEmpty(Password)) return false;
        return true;
    }
}

class B : A
{
    public string? Phone { get; set; }

    public override bool Validate()
    {
        if (base.Validate()) return false;
        if (string.IsNullOrEmpty(Phone)) return false;
        return true;
    }
}
static class C
{
    public static bool ValidateAccount(I account)
    {
        return account.Validate();
    }
}

class Program
{
    static void Main(string[] args)
    {
        var instance = new B();
        Console.WriteLine(C.ValidateAccount(instance));
    }
}

